<?php
require_once __DIR__ . '/../../includes/db.php';
require_once __DIR__ . '/../includes/auth.php';
require_login();
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $user_id=(int)$_SESSION['user_id'];
    $car_name=trim($_POST['car_name']??'');$plateRaw=strtoupper(trim($_POST['plate_number']??''));$plate_number=$plateRaw===''?null:$plateRaw;$chassis_number=strtoupper(trim($_POST['chassis_number']??''));$purchase_price=(float)($_POST['purchase_price']??0);$purchase_date=$_POST['purchase_date']??'';
    if($car_name===''||$chassis_number===''||$purchase_price<=0||$purchase_date===''){$error='Please fill all required fields correctly.';} else {
        $stmt=$conn->prepare('INSERT INTO cars (user_id,car_name,plate_number,chassis_number,purchase_price,purchase_date) VALUES (?,?,?,?,?,?)');
        $stmt->bind_param('isssds',$user_id,$car_name,$plate_number,$chassis_number,$purchase_price,$purchase_date);
        if($stmt->execute()){
            $id=(int)$stmt->insert_id;
            $stock_type=$_POST['stock_type']??'OWNED';$make=trim($_POST['make']??'');$model=trim($_POST['model']??'');$year=(int)($_POST['model_year']??0);$color=trim($_POST['color']??'');$mileage=(int)($_POST['mileage']??0);$transmission=trim($_POST['transmission']??'');$fuel=trim($_POST['fuel_type']??'');$engine=trim($_POST['engine_number']??'');$asking=(float)($_POST['asking_price']??0);$supplier=trim($_POST['supplier_name']??'');$supplier_phone=trim($_POST['supplier_phone']??'');$owner=trim($_POST['owner_name']??'');$owner_phone=trim($_POST['owner_phone']??'');$yard=trim($_POST['yard_location']??'');$notes=trim($_POST['vehicle_notes']??'');
            $up=$conn->prepare('UPDATE cars SET stock_type=?,make=?,model=?,model_year=NULLIF(?,0),color=?,mileage=NULLIF(?,0),transmission=?,fuel_type=?,engine_number=?,asking_price=NULLIF(?,0),supplier_name=?,supplier_phone=?,owner_name=?,owner_phone=?,yard_location=?,vehicle_notes=? WHERE id=?');
            $up->bind_param('sssisisssdssssssi',$stock_type,$make,$model,$year,$color,$mileage,$transmission,$fuel,$engine,$asking,$supplier,$supplier_phone,$owner,$owner_phone,$yard,$notes,$id);$up->execute();
            require_once __DIR__.'/../includes/business_helpers.php'; car_sales_audit($conn,'CREATE','car',$id,'Added vehicle to stock.',null,['car_name'=>$car_name,'plate_number'=>$plate_number,'chassis_number'=>$chassis_number,'purchase_price'=>$purchase_price,'purchase_date'=>$purchase_date]);
            set_flash('success','Car added successfully.');redirect_to('backend/cars/view.php?id='.$id);
        } else {$error='Could not add car. The chassis number, or a supplied plate number, may already exist.';}
    }
}
$page_title='Add Car';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';
?>
<div class="content-page"><h1 class="page-title">Add Car</h1><div class="card form-card"><?php if($error):?><div class="flash-message error" style="position:static;margin-bottom:16px;"><?=e($error)?></div><?php endif;?><form method="post"><h3>Core Vehicle Record</h3><div class="form-row"><div class="form-group"><label>Car Name *</label><input name="car_name" required placeholder="Toyota Mark X"></div><div class="form-group"><label>Plate / Registration Number</label><input name="plate_number" style="text-transform:uppercase" placeholder="Optional for newly imported vehicles"><small class="muted">Leave blank until the vehicle is registered.</small></div></div><div class="form-row"><div class="form-group"><label>Chassis Number *</label><input name="chassis_number" required style="text-transform:uppercase"></div><div class="form-group"><label>Purchase Date *</label><input type="date" name="purchase_date" required></div></div><div class="form-row"><div class="form-group"><label>Purchase Price *</label><input type="number" name="purchase_price" step="0.01" required></div><div class="form-group"><label>Asking / Listing Price</label><input type="number" name="asking_price" step="0.01"></div></div><h3>Sales Inventory Details</h3><div class="form-row"><div class="form-group"><label>Stock Type</label><select name="stock_type"><option value="OWNED">Owned Stock</option><option value="CONSIGNMENT">Consignment</option><option value="TRADE_IN">Trade-in</option></select></div><div class="form-group"><label>Yard / Branch Location</label><input name="yard_location"></div></div><div class="form-row"><div class="form-group"><label>Make</label><input name="make" placeholder="Toyota"></div><div class="form-group"><label>Model</label><input name="model" placeholder="Mark X"></div></div><div class="form-row"><div class="form-group"><label>Model Year</label><input type="number" name="model_year" min="1900" max="2100"></div><div class="form-group"><label>Color</label><input name="color"></div></div><div class="form-row"><div class="form-group"><label>Mileage (km)</label><input type="number" name="mileage" min="0"></div><div class="form-group"><label>Engine Number</label><input name="engine_number"></div></div><div class="form-row"><div class="form-group"><label>Transmission</label><select name="transmission"><option value="">Not specified</option><option>Automatic</option><option>Manual</option><option>CVT</option></select></div><div class="form-group"><label>Fuel Type</label><select name="fuel_type"><option value="">Not specified</option><option>Petrol</option><option>Diesel</option><option>Hybrid</option><option>Electric</option></select></div></div><h3>Source / Ownership</h3><div class="form-row"><div class="form-group"><label>Supplier / Seller Name</label><input name="supplier_name"></div><div class="form-group"><label>Supplier Phone</label><input name="supplier_phone"></div></div><div class="form-row"><div class="form-group"><label>Consignment / Registered Owner</label><input name="owner_name"></div><div class="form-group"><label>Owner Phone</label><input name="owner_phone"></div></div><div class="form-group"><label>Vehicle Notes</label><textarea name="vehicle_notes" rows="3"></textarea></div><button class="btn btn-green" type="submit">Save Car</button><a class="btn btn-dark" href="<?=app_url('backend/cars/list.php')?>">Cancel</a></form></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
